"use client";

import React, {
  useState,
  useEffect,
  useCallback,
  useMemo,
  useRef,
} from "react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { AxiosError, AxiosResponse } from "axios";

import { useAuth } from "@/ui/auth/useAuth";
import { getImageUrl } from "@/utils/utils";

/* =======================================================
 * 型定義
 * ======================================================= */

interface BackendUser {
  id: number;
  name: string;
  email: string;
  email_verified_at: string | null;
}

interface ItemForm {
  item_image: string | null;
  category: string[]; // ← JSON保存前提
  condition: string | null;
  name: string | null;
  brand: string | null; // ← 手入力 → AI 正規化
  explain: string | null;
  price: number | null;
}

interface ServerErrors {
  [key: string]: string | string[] | undefined;
}

/* =======================================================
 * 定数
 * ======================================================= */

const categories = [
  "ファッション",
  "家電",
  "インテリア",
  "レディース",
  "メンズ",
  "コスメ",
  "本",
  "ゲーム",
  "スポーツ",
  "キッチン",
  "ハンドメイド",
  "アクセサリー",
  "おもちゃ",
  "キッズ・ベビー",
];

const conditions = [
  "良好",
  "目立った傷や汚れなし",
  "やや傷や汚れあり",
  "状態が悪い",
];

/* =======================================================
 * Component
 * ======================================================= */

export default function ItemSellPage() {
  const router = useRouter();
  const { isAuthenticated, isLoading: isAuthLoading, apiClient } = useAuth();

  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const [localUser, setLocalUser] = useState<BackendUser | null>(null);
  const [isFetchingProfile, setIsFetchingProfile] = useState(false);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isImageUploading, setIsImageUploading] = useState(false);

  const [serverErrors, setServerErrors] = useState<ServerErrors>({});
  const [successMessage, setSuccessMessage] = useState("");
  const [errorMessage, setErrorMessage] = useState("");

  const [imageRefreshKey, setImageRefreshKey] = useState(0);

  const [form, setForm] = useState<ItemForm>({
    item_image: null,
    category: [],
    condition: null,
    name: null,
    brand: null,
    explain: null,
    price: null,
  });

  /* =======================================================
   * Computed
   * ======================================================= */

  const isPageLoading = useMemo(
    () => isAuthLoading || isFetchingProfile,
    [isAuthLoading, isFetchingProfile],
  );

  const hasVerifiedEmail = useMemo(
    () => !!localUser?.email_verified_at,
    [localUser],
  );

  /* =======================================================
   * Handlers
   * ======================================================= */

  const fetchProfile = useCallback(async () => {
    if (!apiClient || isFetchingProfile) return;
    setIsFetchingProfile(true);
    try {
      const res = await apiClient.get("/api/mypage/profile");
      setLocalUser(res.data.user ?? res.data);
    } catch {
      setLocalUser(null);
    } finally {
      setIsFetchingProfile(false);
    }
  }, [apiClient, isFetchingProfile]);

  const handleFormChange = useCallback(
    (
      e: React.ChangeEvent<
        HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
      >,
    ) => {
      const { name, value } = e.target;
      setForm((prev) => ({
        ...prev,
        [name]: name === "price" ? Number(value) : value,
      }));
    },
    [],
  );

  const handleCategoryChange = useCallback((cat: string) => {
    setForm((prev) => ({
      ...prev,
      category: prev.category.includes(cat)
        ? prev.category.filter((c) => c !== cat)
        : [...prev.category, cat],
    }));
  }, []);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !apiClient) return;

    setIsImageUploading(true);
    try {
      const fd = new FormData();
      fd.append("item_image", file);

      const res = await apiClient.post("/api/upload", fd, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      setForm((p) => ({ ...p, item_image: res.data.image_path }));
      setImageRefreshKey((k) => k + 1);
    } catch {
      setErrorMessage("画像アップロードに失敗しました");
    } finally {
      setIsImageUploading(false);
    }
  };

  const submitItem = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!apiClient) return;

    setIsSubmitting(true);
    try {
      await apiClient.post("/api/items", form);
      router.push("/thanks/sell");
    } catch (e) {
      setErrorMessage("出品に失敗しました");
    } finally {
      setIsSubmitting(false);
    }
  };

  /* =======================================================
   * Auth Guard
   * ======================================================= */

  useEffect(() => {
    if (isAuthLoading || !apiClient) return;

    if (!isAuthenticated) {
      router.replace("/login");
      return;
    }

    if (!localUser) {
      fetchProfile();
      return;
    }

    if (!hasVerifiedEmail) {
      router.replace("/email/verify");
    }
  }, [
    isAuthLoading,
    isAuthenticated,
    apiClient,
    localUser,
    hasVerifiedEmail,
    fetchProfile,
    router,
  ]);

  if (isPageLoading || !localUser) {
    return <p className="p-10">Loading...</p>;
  }

  /* =======================================================
   * Render
   * ======================================================= */

  return (
    <div className="max-w-2xl mx-auto p-8 bg-white rounded-xl shadow">
      <h1 className="text-2xl font-bold mb-6 text-center">商品の出品</h1>

      {/* 画像 */}
      <section className="mb-8">
        {form.item_image && (
          <div className="w-40 h-40 relative mx-auto mb-4">
            <Image
              src={getImageUrl(form.item_image, imageRefreshKey)}
              alt="preview"
              fill
              className="object-cover rounded"
            />
          </div>
        )}
        <button
          type="button"
          onClick={() => fileInputRef.current?.click()}
          className="block mx-auto px-6 py-2 border rounded-full text-red-600 border-red-600"
        >
          画像を選択
        </button>
        <input
          ref={fileInputRef}
          type="file"
          hidden
          onChange={handleImageUpload}
        />
      </section>

      <form onSubmit={submitItem}>
        {/* カテゴリー */}
        <section className="mb-6">
          <label className="font-bold block mb-2">カテゴリー</label>
          <div className="flex flex-wrap gap-2">
            {categories.map((cat, i) => (
              <React.Fragment key={i}>
                <input
                  type="checkbox"
                  id={`cat-${i}`}
                  className="cat-input"
                  checked={form.category.includes(cat)}
                  onChange={() => handleCategoryChange(cat)}
                />
                <label htmlFor={`cat-${i}`} className="cat-label">
                  {cat}
                </label>
              </React.Fragment>
            ))}
          </div>
        </section>

        {/* コンディション */}
        <section className="mb-6">
          <label className="font-bold block mb-2">商品の状態</label>
          <select
            name="condition"
            className="w-full h-11 border rounded px-3"
            value={form.condition ?? ""}
            onChange={handleFormChange}
          >
            <option value="" disabled>
              選択してください
            </option>
            {conditions.map((c) => (
              <option key={c}>{c}</option>
            ))}
          </select>
        </section>

        {/* ブランド */}
        <section className="mb-6">
          <label className="font-bold block mb-1">ブランド</label>
          <input
            name="brand"
            placeholder="例：SONY / ソニー / Apple Inc."
            className="w-full h-11 border rounded px-3"
            value={form.brand ?? ""}
            onChange={handleFormChange}
          />
          <p className="text-xs text-gray-500 mt-1">
            ※ 入力内容は AI により正規化されます
          </p>
        </section>

        {/* 商品名 */}
        <section className="mb-6">
          <label className="font-bold block mb-2">商品名</label>
          <input
            name="name"
            className="w-full h-11 border rounded px-3"
            value={form.name ?? ""}
            onChange={handleFormChange}
          />
        </section>

        {/* 説明 */}
        <section className="mb-6">
          <label className="font-bold block mb-2">商品説明</label>
          <textarea
            name="explain"
            className="w-full border rounded p-3"
            rows={5}
            value={form.explain ?? ""}
            onChange={handleFormChange}
          />
        </section>

        {/* 価格 */}
        <section className="mb-8">
          <label className="font-bold block mb-2">価格</label>
          <input
            name="price"
            type="number"
            className="w-full h-11 border rounded px-3 text-right"
            value={form.price ?? ""}
            onChange={handleFormChange}
          />
        </section>

        <button
          type="submit"
          disabled={isSubmitting}
          className="w-full py-3 bg-red-600 text-white rounded font-bold"
        >
          出品する
        </button>
      </form>

      {/* styles */}
      <style jsx>{`
        .cat-input {
          display: none;
        }
        .cat-label {
          padding: 6px 14px;
          border: 2px solid #ef4444;
          color: #ef4444;
          border-radius: 9999px;
          cursor: pointer;
          font-size: 0.75rem;
          font-weight: 600;
        }
        .cat-input:checked + .cat-label {
          background: #ef4444;
          color: #fff;
        }
      `}</style>
    </div>
  );
}
